<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import {Settings2,Maximize2,EyeOff,RotateCcw} from 'lucide-vue-next';
import {petAppearance,clampPet,nextIdle} from './space-model';
import RobotRig from "./RobotRig.vue";
import {activeCodeProvider,snapshotVersion} from "./code-context";
import {account,plex} from './plex-client';
import {getLearning,putLearning} from './learning-store';
import {registerLearningFlush} from './learning-flush';
import type {SensorHandle} from './input-sensors';
const props=defineProps<{sectionId:string;sectionTitle:string;suspended:boolean;bottomInset?:number}>();
const emit=defineEmits<{open:[value:boolean];dictating:[value:boolean];login:[]}>();
const opened=ref(false),position=ref({x:0,y:0}),viewport=ref({w:1200,h:800}),ready=ref(false),busy=ref(false),draft=ref(''),error=ref(''),voiceStatus=ref(''),partial=ref(''),listening=ref(false),volume=ref(0),messages=ref<{role:'user'|'assistant';content:string;source?:string}[]>([]),log=ref<HTMLElement>(),input=ref<HTMLTextAreaElement>(),pet=ref<HTMLButtonElement>();
const appearance=ref(petAppearance()),settingsOpen=ref(false),idleAction=ref(''),motionPaused=ref(false),reduced=ref(false);
let appearanceDirty=false;
let idleTimer:ReturnType<typeof setTimeout>|undefined,idleEnd:ReturnType<typeof setTimeout>|undefined,lastIdle='',motionQuery:MediaQueryList,prefTimer:ReturnType<typeof setTimeout>|undefined;
const size=computed(()=>({width:108*appearance.value.scale,height:140*appearance.value.scale}));
function clearIdle(){clearTimeout(idleTimer);clearTimeout(idleEnd);idleAction.value='';}
function scheduleIdle(){clearIdle();if(!ready.value||reduced.value||motionPaused.value||props.suspended||!appearance.value.visible||!appearance.value.idleMotion||busy.value||held.value||opened.value)return;idleTimer=setTimeout(()=>{idleAction.value=nextIdle(lastIdle,Math.random());lastIdle=idleAction.value;idleEnd=setTimeout(scheduleIdle,3200);},10000+Math.random()*15000);}
function motionChange(){reduced.value=motionQuery.matches;scheduleIdle();}
async function saveAppearance(){clearTimeout(prefTimer);if(!ready.value||!appearanceDirty)return;const saved={...appearance.value};try{await putLearning('pet:appearance',saved);if(JSON.stringify(saved)===JSON.stringify(appearance.value))appearanceDirty=false;}catch{error.value='小E外观保存失败，请重试。';}}
function show(){appearance.value.visible=true;settingsOpen.value=false;clamp();scheduleIdle();}
function summon(){show();if(!opened.value){moved=false;toggle();}}
async function hide(){await saveDraft();close();settingsOpen.value=false;appearance.value.visible=false;clearIdle();await saveAppearance();}
function resetAppearance(){appearance.value.scale=1;clamp();}
let resizing:{y:number;scale:number}|undefined;
function resizeStart(e:PointerEvent){if(e.button!==0)return;e.preventDefault();clearIdle();resizing={y:e.clientY,scale:appearance.value.scale};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);}
function resizeMove(e:PointerEvent){if(!resizing)return;appearance.value.scale=Math.max(.7,Math.min(2,resizing.scale+(e.clientY-resizing.y)/140));clamp();}
function resizeEnd(e:PointerEvent){resizing=undefined;const el=e.currentTarget as HTMLElement;if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);void saveAppearance();scheduleIdle();}
function resizeKey(e:KeyboardEvent){if(['ArrowUp','ArrowRight','ArrowDown','ArrowLeft','Home'].includes(e.key)){e.preventDefault();appearance.value.scale=e.key==='Home'?1:Math.max(.7,Math.min(2,appearance.value.scale+(['ArrowUp','ArrowRight'].includes(e.key)?.05:-.05)));}}
watch(appearance,()=>{if(!ready.value)return;appearanceDirty=true;clamp();scheduleIdle();clearTimeout(prefTimer);prefTimer=setTimeout(()=>void saveAppearance(),300);},{deep:true});
const failurePose=ref(false);let failureTimer:ReturnType<typeof setTimeout>|undefined;
watch(error,v=>{if(v){failurePose.value=true;clearTimeout(failureTimer);failureTimer=setTimeout(()=>failurePose.value=false,1800);}});
const held=ref(false),landing=ref(false),answer=ref(false),swing=ref(0),includeOutput=ref(false),includeErrors=ref(false),selectionOnly=ref(false);
const contextPreview=computed(()=>activeCodeProvider.value?.());
const actionState=computed(()=>held.value?'grabbed':landing.value?'landing':busy.value?'thinking':failurePose.value?'error':answer.value?'answer':'idle');
let landingTimer:ReturnType<typeof setTimeout>|undefined,answerTimer:ReturnType<typeof setTimeout>|undefined;
function openCode(){show();opened.value=true;emit('open',true);includeOutput.value=false;includeErrors.value=false;selectionOnly.value=false;}
const bubble=computed(()=>{
 const {w,h}=viewport.value,{x,y}=position.value;
 const above=y-20,below=h-y-size.value.height-30,placeAbove=above>=below;
 const height=Math.min(520,h-16,Math.max(Math.min(260,h-16),placeAbove?above:below));
 return {left:Math.max(8,Math.min(x-270,w-Math.min(380,w-16)-8))+'px',top:Math.max(8,Math.min(placeAbove?y-height-12:y+size.value.height+30,h-height-8))+'px',height:height+'px'};
});
let dragging:{x:number;y:number;px:number;py:number}|undefined,moved=false,request:AbortController|undefined,serial=0,speechAbort:AbortController|undefined,speech:SensorHandle|undefined,speechSeq=0,lastResult=0,saveTimer:ReturnType<typeof setTimeout>|undefined,disposed=false;
function clamp(){viewport.value={w:innerWidth,h:innerHeight};position.value=clampPet(position.value.x,position.value.y,appearance.value.scale,innerWidth,innerHeight-(props.bottomInset||0));}
function dragStart(e:PointerEvent){if(e.button!==0)return;clearIdle();moved=false;held.value=true;dragging={x:e.clientX,y:e.clientY,px:position.value.x,py:position.value.y};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);}
function dragMove(e:PointerEvent){if(!dragging)return;const dx=e.clientX-dragging.x,dy=e.clientY-dragging.y;if(Math.hypot(dx,dy)>5)moved=true;if(!moved)return;swing.value=Math.max(-25,Math.min(25,dx/3));position.value={x:dragging.px+dx,y:dragging.py+dy};clamp();}
function dragEnd(e:PointerEvent){held.value=false;landing.value=moved;clearTimeout(landingTimer);landingTimer=setTimeout(()=>landing.value=false,350);dragging=undefined;const target=e.currentTarget as HTMLElement;if(target.hasPointerCapture(e.pointerId))target.releasePointerCapture(e.pointerId);if(moved)void putLearning('pet:position',position.value).catch(()=>error.value='位置保存失败');}
function toggle(){clearIdle();if(moved){moved=false;return;}opened.value=!opened.value;emit('open',opened.value);if(opened.value)nextTick(()=>input.value?.focus({preventScroll:true}));else{stopSpeech();cancel();pet.value?.focus({preventScroll:true});}}
function close(){if(opened.value){opened.value=false;emit('open',false);stopSpeech();cancel();pet.value?.focus({preventScroll:true});}}
function petKey(e:KeyboardEvent){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();position.value.x+=e.key==='ArrowLeft'?-16:e.key==='ArrowRight'?16:0;position.value.y+=e.key==='ArrowUp'?-16:e.key==='ArrowDown'?16:0;clamp();void putLearning('pet:position',position.value).catch(()=>{});}}
async function saveDraft(){clearTimeout(saveTimer);if(!ready.value)return;await putLearning('pet:draft',{text:draft.value}).catch(()=>error.value='草稿保存失败，关闭前请复制文字。');}
watch(draft,()=>{clearTimeout(saveTimer);saveTimer=setTimeout(()=>void saveDraft(),500);});
function cancel(){const waiting=busy.value;serial++;request?.abort();busy.value=false;answer.value=false;if(waiting&&!disposed){failurePose.value=true;clearTimeout(failureTimer);failureTimer=setTimeout(()=>failurePose.value=false,1200);}}
async function send(){if(busy.value||!draft.value.trim())return;error.value='';if(!account()){error.value='请先登录 PLEX 学生账号；你的输入和离线语音仍可使用。';return;}const live=activeCodeProvider.value?.();
 const material=live?{...live,code:selectionOnly.value?live.selection:live.code,selection:selectionOnly.value?live.selection:'',output:includeOutput.value?live.output:'',diagnostics:includeErrors.value?live.diagnostics:''}:undefined;
 if(material&&(!material.code.trim()||Array.from(material.code).length>20000)){error.value='代码为空或超过 20000 字符，请在编辑器中选择片段后发送。';return;}
 if(material)material.version=snapshotVersion(material.code);
 stopSpeech();const text=draft.value.trim(),own=++serial,history=messages.value.slice(-18).map(m=>({role:m.role,content:m.content}));request=new AbortController();busy.value=true;messages.value.push({role:'user',content:text});await nextTick();log.value?.scrollTo({top:log.value.scrollHeight});
 try{const value=await plex<{reply:string;source?:string;code_context_version?:string;code_context_used?:boolean}>('/student/messenger/chat',{message:`当前阅读《星轨编程》：${props.sectionTitle}（${props.sectionId}）。\n我的问题：${text}`,history,...(material?{code_context:material}:{})},'POST',request.signal);if(disposed||own!==serial)return;if(typeof value.reply!=='string'||!value.reply.trim())throw Error('服务端未返回有效答复，请重试');messages.value.push({role:'assistant',content:(material?`[代码快照 ${material.version}]\n`+(value.code_context_version!==material.version?'当前后端尚未确认完整代码上下文，此回复不能视为完整代码答疑。\n':!value.code_context_used?'未获得此代码快照的模型分析结果，本次答复仅为教学提示。\n':'已确认此快照进入模型分析。\n'):'')+value.reply,source:['llm','spark','xfyun_agent','llm_stream'].includes(value.source||'')?'在线模型回复':value.source==='rules'||value.source==='rag'?'服务端教学提示（非模型生成）':'服务端回复（来源未标注）'});answer.value=true;clearTimeout(answerTimer);answerTimer=setTimeout(()=>answer.value=false,5000);messages.value=messages.value.slice(-30);if(draft.value.trim()===text)draft.value='';await saveDraft();await nextTick();log.value?.scrollTo({top:log.value.scrollHeight});}
 catch(e){if(own===serial&&!disposed)error.value='消息未完成：'+String(e)+'。输入已保留，可再次发送。';}finally{if(own===serial)busy.value=false;}}
function stopSpeech(){speechSeq++;speechAbort?.abort();speech?.stop();speech=undefined;listening.value=false;partial.value='';volume.value=0;emit('dictating',false);}
async function dictate(){if(listening.value){stopSpeech();voiceStatus.value='语音输入已停止';return;}stopSpeech();error.value='';voiceStatus.value='加载本机中文模型…';listening.value=true;emit('dictating',true);const own=++speechSeq;speechAbort=new AbortController();const abort=speechAbort;lastResult=0;
 try{const {startVoice}=await import('./input-sensors');if(abort.signal.aborted)return;speech=await startVoice('',abort.signal,(text,final,id)=>{if(own!==speechSeq||abort.signal.aborted)return;const cleaned=text.replace(/\s+/g,'').trim();if(!final){partial.value=cleaned;return;}if(id<=lastResult)return;lastResult=id;partial.value='';if(cleaned)draft.value=(draft.value+(draft.value?'\n':'')+cleaned).slice(0,4000);},v=>volume.value=v,e=>{stopSpeech();voiceStatus.value='识别失败：'+String(e);});if(abort.signal.aborted){speech?.stop();return;}voiceStatus.value='正在听 · 说完后稍停，文字会填入输入框';}
 catch(e){if(!abort.signal.aborted){stopSpeech();voiceStatus.value='语音输入未启动：'+String(e);}}
}
function background(){motionPaused.value=document.hidden||!document.hasFocus();scheduleIdle();if(motionPaused.value){held.value=false;landing.value=false;dragging=undefined;answer.value=false;stopSpeech();voiceStatus.value='离开页面后已停止录音；返回可重新开启。';}}
function expired(){cancel();stopSpeech();messages.value=[];error.value='登录失效，请重新登录；当前输入已保留。';}
watch(()=>props.bottomInset,clamp);
watch(()=>props.suspended,v=>{if(v)stopSpeech();scheduleIdle();});
watch([busy,held,opened],scheduleIdle);
onMounted(async()=>{motionQuery=matchMedia('(prefers-reduced-motion: reduce)');reduced.value=motionQuery.matches;motionQuery.addEventListener('change',motionChange);try{appearance.value=petAppearance(await getLearning('pet:appearance',undefined));position.value={x:innerWidth-144,y:innerHeight-250};const p=await getLearning<{x:number;y:number}|undefined>('pet:position',undefined);if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y))position.value=p;const d=await getLearning('pet:draft',{text:''});if(disposed)return;draft.value=typeof d.text==='string'?d.text.slice(0,4000):'';}catch{error.value='无法读取小E设置，已使用默认外观。';position.value={x:innerWidth-144,y:innerHeight-250};}if(disposed)return;clamp();ready.value=true;scheduleIdle();window.addEventListener('plex-pet-show',show);window.addEventListener('plex-pet-open',summon);window.addEventListener('focus',background);window.addEventListener('plex-code-assistant',openCode);window.addEventListener('resize',clamp);window.addEventListener('blur',background);document.addEventListener('visibilitychange',background);window.addEventListener('plex-session-expired',expired);});
const unregister=registerLearningFlush(async()=>{await saveDraft();await saveAppearance();});onBeforeUnmount(()=>{disposed=true;clearIdle();clearTimeout(prefTimer);motionQuery?.removeEventListener('change',motionChange);window.removeEventListener('plex-pet-show',show);window.removeEventListener('plex-pet-open',summon);window.removeEventListener('focus',background);unregister();void saveDraft();cancel();stopSpeech();window.removeEventListener('plex-code-assistant',openCode);clearTimeout(landingTimer);clearTimeout(answerTimer);clearTimeout(failureTimer);window.removeEventListener('resize',clamp);window.removeEventListener('blur',background);document.removeEventListener('visibilitychange',background);window.removeEventListener('plex-session-expired',expired);});
defineExpose({open:summon});
</script>
<template><div v-show="ready&&!suspended&&appearance.visible" class="ebook-pet" :class="{'motion-paused':motionPaused}" :inert="suspended">
 <div class="pet-anchor" :style="{left:position.x+'px',top:position.y+'px',width:size.width+'px'}"><button ref="pet" class="pet-character" :class="{listening,busy}" :style="{width:size.width+'px',height:(size.height+24)+'px'}" aria-label="小艺阅读助手，点击聊天，拖动移动" :aria-expanded="opened" @pointerdown="dragStart" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="dragEnd" @click="toggle" @keydown.stop="petKey"><RobotRig :state="actionState" :direction="swing" :idle="actionState==='idle'?idleAction:''" :style="{height:size.height+'px'}"/><span>{{listening?'正在听…':busy?'思考中…':'小E · 点我聊聊'}}</span></button><div class="pet-mini-tools" :style="{left:Math.max(8,Math.min(position.x,viewport.w-150))+'px',top:(position.y+size.height+24)+'px'}"><button aria-label="小E外观设置" title="小E外观设置" :aria-expanded="settingsOpen" @click="settingsOpen=!settingsOpen"><Settings2 :size="15"/></button><button role="slider" aria-label="调整小E大小" aria-valuemin="70" aria-valuemax="200" :aria-valuenow="Math.round(appearance.scale*100)" title="拖动缩放小E" @pointerdown="resizeStart" @pointermove="resizeMove" @pointerup="resizeEnd" @pointercancel="resizeEnd" @keydown.stop="resizeKey"><Maximize2 :size="15"/></button><button aria-label="隐藏小E" title="隐藏小E" @click="hide"><EyeOff :size="15"/></button></div></div>
 <section v-if="settingsOpen" class="pet-settings" aria-label="小E外观设置" :style="{left:Math.max(8,Math.min(position.x,viewport.w-264))+'px',top:Math.max(8,Math.min(position.y-185,viewport.h-230))+'px'}" @keydown.esc.stop="settingsOpen=false"><strong>小E · 外观</strong><label>角色大小 {{Math.round(appearance.scale*100)}}%<input aria-label="小E缩放比例" v-model.number="appearance.scale" type="range" min="0.7" max="2" step="0.01"/></label><label><input type="checkbox" v-model="appearance.idleMotion"/>随机小动作</label><button @click="resetAppearance"><RotateCcw :size="14"/>恢复默认大小</button><button @click="settingsOpen=false">完成</button></section>
 <section v-if="opened" class="pet-bubble" :style="bubble" role="dialog" aria-label="小艺聊天气泡" @keydown.esc.stop.prevent="close" @keydown.stop>
 <div class="pet-bubble-heading"><div><strong>小艺 <small>PLEX 小E</small></strong><span>陪你读懂这一页</span></div><button aria-label="关闭聊天气泡" @click="close">×</button></div>
 <p class="pet-context">当前：{{sectionTitle}} <button v-if="!account()" @click="close();emit('login')">登录 PLEX</button></p>
 <details v-if="contextPreview" class="pet-code-preview"><summary>待发送：{{contextPreview.file}} · {{contextPreview.language}} · {{contextPreview.version}}</summary><p>发送时读取最新编辑内容。代码修改后版本同步更新，回复只对应发送时的快照。</p><label><input type="checkbox" v-model="selectionOnly"/>仅发送选中片段</label><label><input type="checkbox" v-model="includeOutput"/>附带输出</label><label><input type="checkbox" v-model="includeErrors"/>附带错误</label><pre>{{selectionOnly?contextPreview.selection:contextPreview.code}}</pre><button @click="activeCodeProvider=null">移除代码上下文</button></details>
 <div ref="log" class="pet-messages" role="log" aria-label="小艺对话记录" aria-live="polite"><p v-if="!messages.length" class="pet-welcome">有什么没想明白的，直接告诉我。也可以点麦克风，把问题说出来。<small>语音在本机转为文字；点击发送后，问题、当前章节和最近对话才会交给 PLEX。</small></p><article v-for="(m,i) in messages" :key="i" :class="m.role"><small>{{m.role==='user'?'你':m.source}}</small><p>{{m.content}}</p></article><p v-if="busy" role="status">正在等待 PLEX 回复…</p></div>
 <p v-if="error" class="pet-error" role="alert">{{error}}</p><div class="pet-compose"><label class="pet-label" for="pet-message">发消息给小艺</label><textarea id="pet-message" ref="input" v-model="draft" maxlength="4000" placeholder="输入问题，或点击语音输入…" @keydown.ctrl.enter.prevent="send" @keydown.meta.enter.prevent="send"/><p v-if="partial" class="pet-partial">识别中：{{partial}}</p><p v-if="voiceStatus" class="pet-voice-status" role="status">{{voiceStatus}}</p><meter v-if="listening" :value="volume" min="0" max="0.3" aria-label="语音输入音量"/><div class="pet-actions"><button :disabled="busy" @click="dictate">{{listening?'停止录音':'语音输入'}}</button><button v-if="busy" @click="cancel">停止等待</button><button :disabled="busy||!draft.trim()" @click="send">发送</button></div><small>Ctrl / ⌘ + Enter 发送 · 语音不会自动发送</small></div>
 </section></div></template>
<style>
.pet-anchor{position:fixed;z-index:690}.pet-mini-tools{pointer-events:none;position:fixed;width:138px;display:flex;justify-content:center;gap:3px;opacity:0;transition:opacity .2s}.pet-anchor:hover .pet-mini-tools,.pet-anchor:focus-within .pet-mini-tools{opacity:1;pointer-events:auto}.pet-mini-tools button{display:grid;place-items:center;min-width:44px;min-height:44px;border-radius:50%;border:1px solid #5c94ad;background:#0b2337;color:#c2ebf6;cursor:pointer;touch-action:none}.pet-settings{position:fixed;z-index:710;width:250px;padding:14px;border:1px solid #75c6d6;background:#0f2539;color:#e2f4fc;border-radius:14px;box-shadow:0 12px 35px #0008;font:12px sans-serif}.pet-settings label{display:block;margin:13px 0}.pet-settings input[type=range]{width:100%;accent-color:#79dfe7}.pet-settings button{padding:8px;border:1px solid #5793ac;background:#183b53;color:#ecfaff;border-radius:6px;margin-right:7px;cursor:pointer}.pet-settings svg{vertical-align:middle;margin-right:5px}.motion-paused .robot-rig *{animation-play-state:paused!important}@media(hover:none){.pet-mini-tools{opacity:1;pointer-events:auto}.pet-mini-tools button{min-width:44px;min-height:44px}}

.pet-character{display:flex;flex-direction:column;align-items:center;position:relative;width:104px;height:148px;background:transparent;border:0;touch-action:none;cursor:grab;padding:0;user-select:none}.pet-character:active{cursor:grabbing}.pet-character img{flex-shrink:0;width:100%;height:126px;object-fit:contain;filter:drop-shadow(0 8px 6px #0008);animation:pet-breathe 3.4s ease-in-out infinite;pointer-events:none;transform-origin:center bottom}.pet-character:hover img{animation:pet-greet .7s ease-in-out infinite alternate}.pet-character.listening img,.pet-character.busy img{animation:pet-greet .9s ease-in-out infinite alternate}.pet-character span{display:block;background:#102f42e8;color:#ceeff9;border:1px solid #5bb9cf;border-radius:20px;font-size:10px;padding:4px;white-space:nowrap}.pet-bubble{position:fixed;z-index:700;width:min(380px,calc(100vw - 16px));max-height:calc(100dvh - 16px);height:520px;display:flex;flex-direction:column;background:#10283b;color:#e7f6fc;border:2px solid #73c7dd;border-radius:18px;box-shadow:0 16px 70px #0009;overflow:hidden}.pet-bubble .pet-bubble-heading{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:#194158}.pet-bubble .pet-bubble-heading div{display:flex;flex-direction:column;gap:3px}.pet-bubble .pet-bubble-heading small,.pet-bubble .pet-bubble-heading span{font-size:11px;color:#b7dce9}.ebook-pet .pet-bubble button{transition:none;font:inherit;font-size:12px;padding:7px 12px;color:#e9f9ff;background:#1b455c;border:1px solid #78a9be;border-radius:7px}.pet-bubble .pet-bubble-heading>button{font-size:20px;line-height:1}.pet-context{font-size:11px;margin:8px 14px;color:#c2d8e3}.pet-messages{overflow:auto;overscroll-behavior:contain;min-height:72px;flex:1;padding:6px 14px}.pet-welcome{font-size:13px;line-height:1.8}.pet-welcome small{display:block;color:#b0ccd8;font-size:11px;margin-top:8px}.pet-messages article{border-radius:9px;background:#173c51;padding:9px 12px;margin:8px 14px 8px 0}.pet-messages article.user{background:#245164;margin:8px 0 8px 20px}.pet-messages article small{font-size:10px;color:#9fe5f1}.pet-messages article p{font-size:13px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;margin:4px 0}.pet-compose{padding:10px 14px;border-top:1px solid #365c71;overflow:auto;flex-shrink:0;max-height:50%}.pet-label{display:block;font-size:11px;margin-bottom:5px}.pet-compose textarea{width:100%;min-height:64px;max-height:140px;resize:vertical;border:1px solid #6b98ac;border-radius:7px;background:#0b1e2f;color:#effaff;font:inherit;font-size:13px;padding:9px}.pet-actions{display:flex;gap:8px;justify-content:space-between;margin:8px 0}.ebook-pet .pet-bubble .pet-actions button:last-child,.ebook-pet .pet-bubble .pet-actions button:last-child:hover{background:#96e1ee;color:#092333;font-weight:700}.pet-bubble button:disabled{opacity:.5}.pet-compose>small,.pet-partial,.pet-voice-status{font-size:10px;color:#bed5e0;margin:5px 0}.pet-error{font-size:12px;line-height:1.5;color:#ffca9f;padding:8px 14px;margin:0;max-height:92px;overflow:auto}.ebook-pet :focus-visible{outline:3px solid #ffe48f;outline-offset:2px}@keyframes pet-breathe{50%{transform:translateY(-5px) rotate(1deg)}}@keyframes pet-greet{to{transform:translateY(-5px) rotate(-4deg)}}@media(prefers-reduced-motion:reduce){.pet-character img,.pet-character:hover img,.pet-character.listening img,.pet-character.busy img{animation:none}}
